import re, json, unicodedata
h=open('/tmp_workspace/oral.html').read()
cards=re.findall(r'href="/virtual/2025/oral/(\d+)">([^<]+)</a>', h)
titles={}
for i,t in cards:
    t=t.strip()
    if t and t!='View full details':
        titles[i]=t
print(len(titles))
json.dump(titles, open('/tmp_workspace/oral_titles.json','w'), indent=1)

def norm(s):
    s=unicodedata.normalize('NFKD', s)
    s=re.sub(r'[^a-z0-9]+','', s.lower())
    return s

d=json.load(open('/tmp_workspace/iccv2025.json'))
by_norm={norm(x['title']):x for x in d}
matched={}
missing=[]
for i,t in titles.items():
    k=norm(t)
    if k in by_norm:
        matched[i]=by_norm[k]
    else:
        missing.append((i,t))
print('matched', len(matched), 'missing', len(missing))
for m in missing: print(m)
json.dump(matched, open('/tmp_workspace/oral_matched.json','w'))
EOF

python3 - <<'EOF'
import re, json, unicodedata, html
d=json.load(open('/tmp_workspace/iccv2025.json'))
titles=json.load(open('/tmp_workspace/oral_titles.json'))
def norm(s):
    s=html.unescape(s)
    s=unicodedata.normalize('NFKD', s)
    return re.sub(r'[^a-z0-9]+','', s.lower())
by_norm={norm(x['title']):x for x in d}
matched={}
missing=[]
for i,t in titles.items():
    k=norm(t)
    if k in by_norm: matched[i]=by_norm[k]
    else: missing.append((i,t))
print('matched',len(matched),'missing',missing)
out=[]
for i,x in matched.items():
    out.append({'event_id':i,'title':html.unescape(titles[i]),'pdf':x['pdf'],'authors':x['author'],'site':x.get('site','')})
json.dump(out, open('/tmp_workspace/orals.json','w'), indent=1)
print(sum(1 for o in out if o['pdf']))
EOF
